public static int countLeaves(BinNode<Integer> t) {
    if (t == null) {
        return 0;
    }
    if (!t.hasLeft() && !t.hasRight()) {
        return 1;
    }
    return countLeaves(t.getLeft()) + countLeaves(t.getRight());
}

public static int maxTree(BinNode<Integer> t) {
    int max = t.getValue();
    if (t.hasLeft()) {
        max = Math.max(max, maxTree(t.getLeft()));
    }
    if (t.hasRight()) {
        max = Math.max(max, maxTree(t.getRight()));
    }
    return max;
}

